#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "symm.h"

/* Include the Exo-generated kernel header. */
#include "generated/symm/symm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
      B[i][j] = (DATA_TYPE) ((n+i-j) % 100) / m;
    }
  for (i = 0; i < m; i++) {
    for (j = 0; j <=i; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
    for (j = i+1; j < m; j++)
      A[i][j] = -999; //regions of arrays that should not be used
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Optimized SYMM kernel.
#
# Key ideas:
#   - Restructure the computation so that the innermost loops iterate over j
#     (the column index), which gives unit-stride access to both B and C
#     because they are stored in row-major order.
#   - Precompute alpha * B[i, j] into a temporary row buffer (temp1) so that
#     this product is formed once per (i, j) instead of once per (i, j, k).
#   - Accumulate the "temp2" term for all j at once in a second row buffer
#     (temp2), preserving the original BLAS SYMM semantics.
#   - Apply loop tiling and unrolling to the hot k–j nest to improve cache
#     behavior and expose instruction-level parallelism.

@proc
def kernel_symm(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[m, n] @ DRAM,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    # Working buffers reused across all rows i.
    # temp1[j] = alpha * B[i, j]
    # temp2[j] = sum_{k < i} B[k, j] * A[i, k]
    temp1: DATA_TYPE[n]
    temp2: DATA_TYPE[n]

    for i in seq(0, m):
        # Precompute alpha * B[i, j] and zero accumulators for this row i.
        for j in seq(0, n):
            temp1[j] = alpha * B[i, j]
            temp2[j] = 0

        # Main update:
        #   - C[k, j] += alpha * B[i, j] * A[i, k]
        #   - temp2[j] += B[k, j] * A[i, k]
        #
        # By iterating with j innermost we get unit-stride access to rows of
        # both C and B and reuse A[i, k] and temp1[j] effectively.
        for k in seq(0, i):
            aik: DATA_TYPE
            aik = A[i, k]
            for j in seq(0, n):
                C[k, j] += temp1[j] * aik
                temp2[j] += B[k, j] * aik

        # Final update for row i:
        #   C[i, j] = beta * C[i, j] +
        #             alpha * B[i, j] * A[i, i] +
        #             alpha * sum_{k < i} B[k, j] * A[i, k]
        aii: DATA_TYPE
        aii = A[i, i]
        for j in seq(0, n):
            C[i, j] = beta * C[i, j] + temp1[j] * aii + alpha * temp2[j]


# ---------------------------------------------------------------------------
# Scheduling: tile and unroll the inner j loop in the hot k–j nest.
# This improves spatial locality for C and B and exposes ILP.
# ---------------------------------------------------------------------------

tile_size_j = 32  # tuning parameter for j-tiling

# Find the k loop of the main update and then the j loop immediately inside it.
k_loop = kernel_symm.find_loop("k")
j_loop_in_k = k_loop.body().find_loop("j")

# 1. Tile the j loop inside the k loop: j -> (jo, ji)
kernel_symm = divide_loop(
    kernel_symm,
    j_loop_in_k,
    tile_size_j,
    ("jo", "ji"),
    tail="guard",
)

# 2. Unroll the small inner tile loop (ji) to expose ILP in the unit-stride loop.
ji_loop = kernel_symm.find_loop("ji")
kernel_symm = unroll_loop(kernel_symm, ji_loop)

# 3. Simplify to clean up guards and algebraic redundancies after tiling/unrolling.
kernel_symm = simplify(kernel_symm)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_symm (/*ctxt=*/NULL, m, n,
	       (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
	       (DATA_TYPE*)POLYBENCH_ARRAY(C),
	       (DATA_TYPE*)POLYBENCH_ARRAY(A),
	       (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
