/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


# Baseline symmetric matrix-matrix multiply kernel:
#   C = beta * C + alpha * (A * B + B * A)
# specialized to the storage pattern used in PolyBench's SYMM benchmark
# (A is stored as a lower-triangular symmetric matrix).
@proc
def kernel_symm_base(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[m, n] @ DRAM,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    # Step 1: scale C by beta and add the diagonal contribution
    #         alpha * A[i, i] * B[i, j].
    #
    # This loop touches each element of C and B exactly once with unit-stride
    # access along j, which is cache- and vector-friendly.
    for i in seq(0, m):
        for j in seq(0, n):
            C[i, j] = beta * C[i, j] + alpha * B[i, j] * A[i, i]

    # Step 2: accumulate the strictly lower-triangular part of A.
    # For each row i, we update rows 0..i-1 and row i of C.
    #
    # Mathematically, this reproduces the original PolyBench SYMM kernel:
    #   - For k < i, C[k, j] receives alpha * A[i, k] * B[i, j]
    #   - Row i accumulates alpha * sum_{k < i} A[i, k] * B[k, j]
    # combined with the diagonal update from step 1.
    for i in seq(0, m):
        # Temporary buffer accumulating contributions to row i across all k < i.
        # Size n is small compared to the full matrices (M x N), so this stays
        # well within the memory overhead budget.
        temp2: DATA_TYPE[n]

        # Initialize the accumulation buffer for this row i.
        for j in seq(0, n):
            temp2[j] = 0

        # Process all columns k below the diagonal in row i.
        # We read A[i, k] once per k and then reuse it across the entire
        # inner j-loop, greatly improving locality for A compared to the
        # original i-j-k ordering.
        for k in seq(0, i):
            a_ik: DATA_TYPE
            a_ik = A[i, k]

            # The inner j-loop has unit-stride accesses in B, C, and temp2.
            #   - C[k, j]: row-major, contiguous in j
            #   - B[i, j], B[k, j]: contiguous rows
            #   - temp2[j]: contiguous
            for j in seq(0, n):
                C[k, j] += alpha * a_ik * B[i, j]
                temp2[j] += a_ik * B[k, j]

        # Finish the symmetric update of row i using the accumulated temp2.
        for j in seq(0, n):
            C[i, j] += alpha * temp2[j]


# ---------------------------------------------------------------------------
# Scheduling: improve memory locality and expose parallelism.
# ---------------------------------------------------------------------------

# Start from the baseline kernel and rename it to the exported name
# expected by the C driver.
kernel_symm = rename(kernel_symm_base, "kernel_symm")

# Hoist the temporary buffer 'temp2' so it is allocated once outside the
# second i-loop instead of once per iteration. We still explicitly zero
# it inside the loop, so semantics are unchanged.
temp2_alloc = kernel_symm.find("temp2 : _")
kernel_symm = lift_alloc(kernel_symm, temp2_alloc, n_lifts=1)

# Parallelize the j-loop in the first phase (scaling C and adding the
# diagonal contribution). Different j-iterations operate on disjoint
# columns of C and B, so they are safely parallelizable.
kernel_symm = parallelize_loop(kernel_symm, "j")

# Tile the most intensive j-loop (the one inside the k-loop in the second
# phase) to improve cache behavior over rows of B, C, and the temp2 buffer.
# J_TILE is a tunable parameter that can be adapted to the target cache size.
J_TILE = 64

# "j #2" refers to the third j-loop in the procedure:
#   - #0 : first-phase j-loop  (already parallelized)
#   - #1 : zeroing temp2
#   - #2 : inner j-loop inside the k-loop (the hot loop)
#   - #3 : final accumulation into C[i, j]
kernel_symm = divide_loop(kernel_symm, "j #2", J_TILE,
                          ["j_outer", "j_inner"],
                          tail="guard")

# Clean up the resulting control structure and arithmetic expressions.
kernel_symm = simplify(kernel_symm)

EXO END
*/


